  {'id': 'dep_clean_surface_5m', 'title': 'Clear One Surface', 'description': 'Pick one counter, table, or desk and clear it off completely. One clean surface can shift your whole environment.', 'conditionType': 'depression', 'category': 'organizationalTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
