  {'id': 'dep_write_letter_15m', 'title': 'Write a Letter', 'description': 'Write a letter to someone — by hand or digitally. Express something you appreciate about them. You can send it or keep it.', 'conditionType': 'depression', 'category': 'socialTask', 'durationMinutes': 15, 'timeOfDay': 'evening', 'difficulty': 'medium'},
  {'id': 'dep_plan_outing_10m', 'title': 'Plan a Social Outing', 'description': 'Plan one social activity for the next few days — coffee, a walk, lunch. Making plans creates something to look forward to.', 'conditionType': 'depression', 'category': 'socialTask', 'durationMinutes': 10, 'timeOfDay': 'afternoon', 'difficulty': 'medium'},
