  {'id': 'dep_read_20m', 'title': 'Read for 20 Minutes', 'description': 'Spend 20 minutes lost in a book. Reading transports your mind and gives you a break from depressive rumination.', 'conditionType': 'depression', 'category': 'selfCareTask', 'durationMinutes': 20, 'timeOfDay': 'evening', 'difficulty': 'easy'},
  {'id': 'dep_shower_10m', 'title': 'Refreshing Shower', 'description': 'Take a shower. Focus on the sensation of water on your skin. Let it be a ritual of refreshing yourself, not just cleaning.', 'conditionType': 'depression', 'category': 'selfCareTask', 'durationMinutes': 10, 'timeOfDay': 'morning', 'difficulty': 'easy'},
  {'id': 'dep_bath_20m', 'title': 'Warm Bath', 'description': 'Run a warm bath and soak for 20 minutes. Add salts or bubbles if you have them. Let the warmth ease your body and mind.', 'conditionType': 'depression', 'category': 'selfCareTask', 'durationMinutes': 20, 'timeOfDay': 'evening', 'difficulty': 'easy'},
