  {'id': 'dep_puzzle_15m', 'title': 'Do a Puzzle', 'description': 'Work on a puzzle — jigsaw, crossword, Sudoku, word search. Puzzles engage your brain in a low-pressure, satisfying way.', 'conditionType': 'depression', 'category': 'cognitiveTask', 'durationMinutes': 15, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
