  {'id': 'dep_plan_tomorrow_10m', 'title': 'Plan Tomorrow', 'description': 'Write down 3 things you\'ll do tomorrow. Keep them small and achievable. Having a plan gives structure to face the day.', 'conditionType': 'depression', 'category': 'organizationalTask', 'durationMinutes': 10, 'timeOfDay': 'evening', 'difficulty': 'easy'},
  {'id': 'dep_small_goal_5m', 'title': 'Set One Small Goal', 'description': 'Set one tiny, achievable goal for today. "I will drink a glass of water" counts. Check it off when you\'re done.', 'conditionType': 'depression', 'category': 'organizationalTask', 'durationMinutes': 5, 'timeOfDay': 'morning', 'difficulty': 'easy'},
