  // ═══════════════════════════════════════════════════════════════════════════
  // DEPRESSION — Thought Challenging
  // ═══════════════════════════════════════════════════════════════════════════
  {'id': 'dep_thought_challenge_10m', 'title': 'Challenge Negative Thought', 'description': 'Write a negative thought. Ask: Is this thought a fact? What evidence supports and contradicts it? Rewrite it more balanced.', 'conditionType': 'depression', 'category': 'cognitiveTask', 'durationMinutes': 10, 'timeOfDay': 'anytime', 'difficulty': 'medium'},
  {'id': 'dep_evidence_check_10m', 'title': 'Evidence Checking', 'description': 'Take your darkest thought right now. List every piece of evidence for it AND against it. Which list is longer and stronger?', 'conditionType': 'depression', 'category': 'cognitiveTask', 'durationMinutes': 10, 'timeOfDay': 'anytime', 'difficulty': 'medium'},
  {'id': 'dep_distortion_id_10m', 'title': 'Identify Cognitive Distortion', 'description': 'Write a negative thought and identify which thinking trap it falls into: all-or-nothing, catastrophizing, mind reading, or labeling.', 'conditionType': 'depression', 'category': 'cognitiveTask', 'durationMinutes': 10, 'timeOfDay': 'anytime', 'difficulty': 'medium'},
  {'id': 'dep_reframe_10m', 'title': 'Reframe Negative Thought', 'description': 'Take a depressive thought and write 3 alternative, more balanced ways to see the same situation.', 'conditionType': 'depression', 'category': 'cognitiveTask', 'durationMinutes': 10, 'timeOfDay': 'anytime', 'difficulty': 'medium'},
  {'id': 'dep_friend_perspective_5m', 'title': 'Friend Perspective', 'description': 'If your best friend had this thought, what would you say to them? Write it down, then read it back to yourself.', 'conditionType': 'depression', 'category': 'cognitiveTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_all_or_nothing_5m', 'title': 'All-or-Nothing Check', 'description': 'Are you thinking in extremes? "I always fail" or "Nothing ever works." Find the gray area — the middle ground that\'s more true.', 'conditionType': 'depression', 'category': 'cognitiveTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_should_challenge_5m', 'title': 'Should Statement Challenge', 'description': 'Notice any "should" statements: "I should be doing more." Replace with "I could" or "I would like to." Feel the difference.', 'conditionType': 'depression', 'category': 'cognitiveTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_label_check_5m', 'title': 'Labeling Check', 'description': 'Are you labeling yourself? "I\'m a failure" vs "I had a setback." Separate who you are from what happened.', 'conditionType': 'depression', 'category': 'cognitiveTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_catastrophe_check_5m', 'title': 'Catastrophizing Check', 'description': 'Is your mind jumping to the worst case? Rate its actual probability 0-100%. What\'s the most realistic outcome instead?', 'conditionType': 'depression', 'category': 'cognitiveTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_fortune_tell_check_5m', 'title': 'Fortune Telling Check', 'description': 'Are you predicting bad outcomes? List times your predictions were wrong. You can\'t see the future — and that might be good.', 'conditionType': 'depression', 'category': 'cognitiveTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},

  // ═══════════════════════════════════════════════════════════════════════════
  // DEPRESSION — Gratitude, Pleasure Scheduling, Accomplishments
  // ═══════════════════════════════════════════════════════════════════════════
  {'id': 'dep_gratitude_3_5m', 'title': 'Three Gratitudes', 'description': 'Write down 3 things you\'re grateful for today. They can be tiny — warm socks, a good meal, someone\'s smile.', 'conditionType': 'depression', 'category': 'journalingTask', 'durationMinutes': 5, 'timeOfDay': 'evening', 'difficulty': 'easy'},
  {'id': 'dep_gratitude_detail_10m', 'title': 'Detailed Gratitude Entry', 'description': 'Pick one thing you\'re grateful for and write about it in detail. Why does it matter? How does it make your life better?', 'conditionType': 'depression', 'category': 'journalingTask', 'durationMinutes': 10, 'timeOfDay': 'evening', 'difficulty': 'easy'},
  {'id': 'dep_gratitude_letter_15m', 'title': 'Gratitude Letter', 'description': 'Write a letter of gratitude to someone who has positively impacted your life. You don\'t have to send it to feel the benefit.', 'conditionType': 'depression', 'category': 'journalingTask', 'durationMinutes': 15, 'timeOfDay': 'evening', 'difficulty': 'medium'},
  {'id': 'dep_gratitude_photo_10m', 'title': 'Gratitude Photo', 'description': 'Take a photo of something you\'re grateful for and write a sentence about why. Build a visual gratitude collection.', 'conditionType': 'depression', 'category': 'creativeTask', 'durationMinutes': 10, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_gratitude_person_10m', 'title': 'Grateful for a Person', 'description': 'Think of one person you\'re grateful for. Write down 3 specific things they\'ve done that mattered to you.', 'conditionType': 'depression', 'category': 'journalingTask', 'durationMinutes': 10, 'timeOfDay': 'evening', 'difficulty': 'easy'},
  {'id': 'dep_pleasure_plan_10m', 'title': 'Plan a Pleasurable Activity', 'description': 'Schedule one enjoyable activity for today or tomorrow. It can be simple: a favorite snack, a show, a walk in a nice spot.', 'conditionType': 'depression', 'category': 'organizationalTask', 'durationMinutes': 10, 'timeOfDay': 'morning', 'difficulty': 'easy'},
  {'id': 'dep_pleasure_micro_5m', 'title': 'Micro-Pleasure Break', 'description': 'Take 5 minutes to do something purely enjoyable — smell a flower, eat chocolate, pet an animal, feel sunshine.', 'conditionType': 'depression', 'category': 'selfCareTask', 'durationMinutes': 5, 'timeOfDay': 'afternoon', 'difficulty': 'easy'},
  {'id': 'dep_pleasure_list_10m', 'title': 'Pleasure Activities List', 'description': 'Create a list of 20 activities that bring you even small amounts of pleasure. Keep this list handy for low-motivation days.', 'conditionType': 'depression', 'category': 'journalingTask', 'durationMinutes': 10, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_reward_plan_5m', 'title': 'Plan a Reward', 'description': 'Choose a reward for getting through today — a favorite meal, a show, a treat. Having something to look forward to helps.', 'conditionType': 'depression', 'category': 'selfCareTask', 'durationMinutes': 5, 'timeOfDay': 'morning', 'difficulty': 'easy'},
  {'id': 'dep_joy_recall_5m', 'title': 'Recall a Joyful Memory', 'description': 'Close your eyes and recall a time you felt truly happy. Relive the details. Joy leaves traces in the brain you can revisit.', 'conditionType': 'depression', 'category': 'mindfulness', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_accomplish_log_5m', 'title': 'Log Today\'s Accomplishments', 'description': 'Write down everything you did today, no matter how small. Got out of bed? Ate? Brushed teeth? Those count. Celebrate them.', 'conditionType': 'depression', 'category': 'journalingTask', 'durationMinutes': 5, 'timeOfDay': 'evening', 'difficulty': 'easy'},
  {'id': 'dep_win_list_5m', 'title': 'List 3 Small Wins', 'description': 'Name 3 things you accomplished today. They don\'t have to be big. Noticing your wins rewires your brain for progress.', 'conditionType': 'depression', 'category': 'journalingTask', 'durationMinutes': 5, 'timeOfDay': 'evening', 'difficulty': 'easy'},
  {'id': 'dep_progress_review_10m', 'title': 'Weekly Progress Review', 'description': 'Review your week. What did you accomplish? What challenged you? What small progress can you celebrate?', 'conditionType': 'depression', 'category': 'journalingTask', 'durationMinutes': 10, 'timeOfDay': 'evening', 'difficulty': 'medium'},
  {'id': 'dep_strength_id_5m', 'title': 'Identify a Strength', 'description': 'Name one personal strength you used today. Persistence? Kindness? Patience? You have strengths even on hard days.', 'conditionType': 'depression', 'category': 'cognitiveTask', 'durationMinutes': 5, 'timeOfDay': 'evening', 'difficulty': 'easy'},
  {'id': 'dep_celebrate_3m', 'title': 'Celebrate One Achievement', 'description': 'Pick one thing you did today and celebrate it deliberately. Smile, say "I did that," or tell someone about it.', 'conditionType': 'depression', 'category': 'selfCareTask', 'durationMinutes': 3, 'timeOfDay': 'evening', 'difficulty': 'easy'},

  // ═══════════════════════════════════════════════════════════════════════════
  // DEPRESSION — Routine, Mindfulness & Values
  // ═══════════════════════════════════════════════════════════════════════════
  {'id': 'dep_morning_routine_15m', 'title': 'Morning Routine', 'description': 'Follow a simple morning routine: get up, wash face, brush teeth, drink water, eat something, get dressed. Check each one off.', 'conditionType': 'depression', 'category': 'selfCareTask', 'durationMinutes': 15, 'timeOfDay': 'morning', 'difficulty': 'easy'},
  {'id': 'dep_evening_routine_15m', 'title': 'Evening Routine', 'description': 'Do a calming evening routine: tidy one thing, brush teeth, skincare, prepare tomorrow\'s clothes, get into bed at a set time.', 'conditionType': 'depression', 'category': 'selfCareTask', 'durationMinutes': 15, 'timeOfDay': 'evening', 'difficulty': 'easy'},
  {'id': 'dep_meal_prep_15m', 'title': 'Prepare a Healthy Meal', 'description': 'Make a balanced meal with protein, vegetables, and whole grains. Nourishing your body is an act of self-love.', 'conditionType': 'depression', 'category': 'selfCareTask', 'durationMinutes': 15, 'timeOfDay': 'anytime', 'difficulty': 'medium'},
  {'id': 'dep_hydrate_track_5m', 'title': 'Track Water Intake', 'description': 'Drink a full glass of water right now and track your intake today. Dehydration worsens mood and fatigue.', 'conditionType': 'depression', 'category': 'selfCareTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_sleep_hygiene_10m', 'title': 'Sleep Hygiene Check', 'description': 'Review your sleep habits: consistent bed/wake times, dark room, no screens before bed, comfortable temperature. Fix one thing.', 'conditionType': 'depression', 'category': 'selfCareTask', 'durationMinutes': 10, 'timeOfDay': 'evening', 'difficulty': 'easy'},
  {'id': 'dep_fresh_air_5m', 'title': 'Step Outside for Fresh Air', 'description': 'Open the door and step outside for 5 minutes. Fresh air and a change of environment can shift your state.', 'conditionType': 'depression', 'category': 'physicalTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_get_dressed_10m', 'title': 'Get Dressed with Intention', 'description': 'Put on real clothes — not pajamas. Choose something that makes you feel a little more put together. It shifts your mindset.', 'conditionType': 'depression', 'category': 'selfCareTask', 'durationMinutes': 10, 'timeOfDay': 'morning', 'difficulty': 'easy'},
  {'id': 'dep_meditate_5m', 'title': '5 Minute Meditation', 'description': 'Sit quietly and focus on your breath for 5 minutes. When your mind wanders, gently return to the breath. No judgment.', 'conditionType': 'depression', 'category': 'mindfulness', 'durationMinutes': 5, 'timeOfDay': 'morning', 'difficulty': 'easy'},
  {'id': 'dep_meditate_10m', 'title': '10 Minute Meditation', 'description': 'A 10-minute meditation focusing on breath awareness. Allow thoughts to come and go like passing clouds.', 'conditionType': 'depression', 'category': 'mindfulness', 'durationMinutes': 10, 'timeOfDay': 'morning', 'difficulty': 'medium'},
  {'id': 'dep_body_scan_10m', 'title': 'Body Scan Meditation', 'description': 'Lie down and scan from toes to head, noticing sensations. Where do you carry heaviness? Breathe into those areas.', 'conditionType': 'depression', 'category': 'mindfulness', 'durationMinutes': 10, 'timeOfDay': 'evening', 'difficulty': 'easy'},
  {'id': 'dep_mindful_walk_10m', 'title': 'Mindful Walking', 'description': 'Walk slowly for 10 minutes, paying attention to each step, the air on your skin, the sounds around you.', 'conditionType': 'depression', 'category': 'mindfulness', 'durationMinutes': 10, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_breath_aware_5m', 'title': 'Breath Awareness', 'description': 'Simply watch your natural breath for 5 minutes. Don\'t change it. Just observe the inhale and exhale. Be present.', 'conditionType': 'depression', 'category': 'mindfulness', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_values_reflect_10m', 'title': 'Values Reflection', 'description': 'Write about what matters most to you. What kind of person do you want to be? How can you take one small step toward that today?', 'conditionType': 'depression', 'category': 'journalingTask', 'durationMinutes': 10, 'timeOfDay': 'morning', 'difficulty': 'medium'},
  {'id': 'dep_meaning_find_10m', 'title': 'Find Meaning Today', 'description': 'Identify one meaningful thing about today. Even on dark days, there is something: a kind word, a lesson, a moment of peace.', 'conditionType': 'depression', 'category': 'journalingTask', 'durationMinutes': 10, 'timeOfDay': 'evening', 'difficulty': 'medium'},
  {'id': 'dep_purpose_5m', 'title': 'Purpose Statement', 'description': 'Write a one-sentence purpose statement for today. "Today, my purpose is to ___." Make it small and achievable.', 'conditionType': 'depression', 'category': 'journalingTask', 'durationMinutes': 5, 'timeOfDay': 'morning', 'difficulty': 'easy'},
  {'id': 'dep_kindness_act_5m', 'title': 'Random Act of Kindness', 'description': 'Do one kind thing for someone — hold a door, send an encouraging text, leave a nice note. Kindness benefits the giver too.', 'conditionType': 'depression', 'category': 'socialTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_legacy_think_10m', 'title': 'Legacy Thinking', 'description': 'What do you want people to remember about you? Write about it. Connecting to your legacy reignites purpose.', 'conditionType': 'depression', 'category': 'journalingTask', 'durationMinutes': 10, 'timeOfDay': 'evening', 'difficulty': 'challenge'},
  {'id': 'dep_playlist_create_10m', 'title': 'Create an Uplifting Playlist', 'description': 'Build a playlist of songs that lift your mood. Add at least 10 songs. Play it whenever you need a boost.', 'conditionType': 'depression', 'category': 'creativeTask', 'durationMinutes': 10, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_nature_journal_10m', 'title': 'Nature Journal Entry', 'description': 'Go outside and write about what you observe in nature — the light, the air, the sounds. Nature journaling quiets the mind.', 'conditionType': 'depression', 'category': 'journalingTask', 'durationMinutes': 10, 'timeOfDay': 'morning', 'difficulty': 'easy'},
  {'id': 'dep_comfort_food_15m', 'title': 'Cook Comfort Food', 'description': 'Make a comforting food from your childhood or culture. The smells and tastes connect you to warm memories.', 'conditionType': 'depression', 'category': 'selfCareTask', 'durationMinutes': 15, 'timeOfDay': 'evening', 'difficulty': 'medium'},
  {'id': 'dep_rearrange_10m', 'title': 'Rearrange a Space', 'description': 'Move some furniture or objects around in a room. A fresh arrangement creates a sense of newness and control.', 'conditionType': 'depression', 'category': 'organizationalTask', 'durationMinutes': 10, 'timeOfDay': 'afternoon', 'difficulty': 'medium'},
  {'id': 'dep_list_loves_5m', 'title': 'List Things You Love', 'description': 'Write a list of 10 things you love — people, places, activities, foods, memories. Keep this list for hard days.', 'conditionType': 'depression', 'category': 'journalingTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'dep_laugh_5m', 'title': 'Find Something to Laugh At', 'description': 'Watch a funny video, read a comic, or recall a hilarious memory. Laughter reduces cortisol and boosts endorphins.', 'conditionType': 'depression', 'category': 'selfCareTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},

  // ═══════════════════════════════════════════════════════════════════════════
  // ADHD — Focus Micro-Sessions
  // ═══════════════════════════════════════════════════════════════════════════
  {'id': 'adhd_focus_5m', 'title': '5 Minute Focus Sprint', 'description': 'Set a timer for 5 minutes. Work on one thing only until it rings. Then decide if you want to keep going.', 'conditionType': 'adhd', 'category': 'focusTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_focus_10m', 'title': '10 Minute Focus Block', 'description': 'Commit to 10 minutes of focused work on a single task. Close other tabs, put your phone away, and begin.', 'conditionType': 'adhd', 'category': 'focusTask', 'durationMinutes': 10, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_focus_15m', 'title': '15 Minute Focus Sprint', 'description': 'A 15-minute focused work sprint. Set the timer, silence notifications, and give this one task your full attention.', 'conditionType': 'adhd', 'category': 'focusTask', 'durationMinutes': 15, 'timeOfDay': 'morning', 'difficulty': 'medium'},
  {'id': 'adhd_focus_25m', 'title': 'Pomodoro Session', 'description': 'A full 25-minute Pomodoro: focused work with no interruptions. Followed by a 5-minute break. You\'ve got this.', 'conditionType': 'adhd', 'category': 'focusTask', 'durationMinutes': 25, 'timeOfDay': 'morning', 'difficulty': 'medium'},
  {'id': 'adhd_focus_deep_50m', 'title': 'Deep Focus Block', 'description': 'A 50-minute deep work session. Clear your environment, set a timer, and commit fully. Take a 10-minute break after.', 'conditionType': 'adhd', 'category': 'focusTask', 'durationMinutes': 50, 'timeOfDay': 'morning', 'difficulty': 'challenge'},
  {'id': 'adhd_micro_3m', 'title': '3 Minute Micro-Focus', 'description': 'Can\'t face a big task? Do just 3 minutes of it. Often starting is the hardest part — momentum takes over.', 'conditionType': 'adhd', 'category': 'focusTask', 'durationMinutes': 3, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_focus_music_15m', 'title': 'Focus with Music', 'description': 'Put on focus music (lo-fi, classical, brown noise) and work for 15 minutes. The audio creates an anchor for attention.', 'conditionType': 'adhd', 'category': 'focusTask', 'durationMinutes': 15, 'timeOfDay': 'anytime', 'difficulty': 'easy'},

  // ═══════════════════════════════════════════════════════════════════════════
  // ADHD — 5-Minute Rule
  // ═══════════════════════════════════════════════════════════════════════════
  {'id': 'adhd_5min_rule_5m', 'title': '5-Minute Rule Start', 'description': 'Pick the task you\'re avoiding most. Do it for exactly 5 minutes. If you want to stop after 5 minutes, you can.', 'conditionType': 'adhd', 'category': 'focusTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_5min_clean_5m', 'title': '5-Min Clean Burst', 'description': 'Set a timer for 5 minutes and clean as much as you can. Speed-clean like it\'s a game. Stop when the timer rings.', 'conditionType': 'adhd', 'category': 'organizationalTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_5min_write_5m', 'title': '5-Min Writing Burst', 'description': 'Write for 5 minutes without stopping. Don\'t edit, don\'t overthink. Just put words on paper about anything.', 'conditionType': 'adhd', 'category': 'focusTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_5min_sort_5m', 'title': '5-Min Sort and Organize', 'description': 'Pick a pile or area and sort it for 5 minutes. Trash, keep, relocate. Don\'t think too hard — just sort.', 'conditionType': 'adhd', 'category': 'organizationalTask', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_5min_email_5m', 'title': '5-Min Email Blast', 'description': 'Open your email and respond to as many messages as you can in 5 minutes. Quick replies only. Go!', 'conditionType': 'adhd', 'category': 'focusTask', 'durationMinutes': 5, 'timeOfDay': 'morning', 'difficulty': 'easy'},

  // ═══════════════════════════════════════════════════════════════════════════
  // ADHD — Body Doubling
  // ═══════════════════════════════════════════════════════════════════════════
  {'id': 'adhd_body_double_15m', 'title': 'Virtual Body Doubling', 'description': 'Join a virtual co-working session or stream. Having someone else working alongside you (even virtually) boosts focus.', 'conditionType': 'adhd', 'category': 'focusTask', 'durationMinutes': 15, 'timeOfDay': 'morning', 'difficulty': 'easy'},
  {'id': 'adhd_body_double_25m', 'title': 'Body Doubling Work Session', 'description': 'Work alongside someone (in person or video call) for 25 minutes. Their presence helps you stay on task.', 'conditionType': 'adhd', 'category': 'focusTask', 'durationMinutes': 25, 'timeOfDay': 'morning', 'difficulty': 'medium'},
  {'id': 'adhd_parallel_work_15m', 'title': 'Parallel Work with Friend', 'description': 'Text a friend and work on your own tasks at the same time. Check in halfway through. Shared accountability works.', 'conditionType': 'adhd', 'category': 'socialTask', 'durationMinutes': 15, 'timeOfDay': 'afternoon', 'difficulty': 'easy'},
  {'id': 'adhd_cowork_video_25m', 'title': 'Co-work Video Session', 'description': 'Set up a video call with someone, each doing your own work. State your intentions at the start. Report at the end.', 'conditionType': 'adhd', 'category': 'socialTask', 'durationMinutes': 25, 'timeOfDay': 'morning', 'difficulty': 'medium'},
  {'id': 'adhd_accountability_5m', 'title': 'Accountability Check-in', 'description': 'Tell someone what you plan to accomplish in the next hour. Later, report back. External accountability supercharges ADHD brains.', 'conditionType': 'adhd', 'category': 'socialTask', 'durationMinutes': 5, 'timeOfDay': 'morning', 'difficulty': 'easy'},

  // ═══════════════════════════════════════════════════════════════════════════
  // ADHD — Dopamine Menu
  // ═══════════════════════════════════════════════════════════════════════════
  {'id': 'adhd_dance_break_5m', 'title': 'Dance Break', 'description': 'Put on an energizing song and dance for the whole thing. This healthy dopamine hit recharges your focus.', 'conditionType': 'adhd', 'category': 'dopamineBoost', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_cold_water_2m', 'title': 'Cold Water Splash', 'description': 'Splash cold water on your face or run your wrists under cold water. The shock wakes up your nervous system instantly.', 'conditionType': 'adhd', 'category': 'dopamineBoost', 'durationMinutes': 2, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_jumping_jacks_3m', 'title': 'Jumping Jacks Burst', 'description': 'Do jumping jacks for 3 minutes. The burst of movement floods your brain with dopamine and norepinephrine.', 'conditionType': 'adhd', 'category': 'dopamineBoost', 'durationMinutes': 3, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_sketch_10m', 'title': 'Quick Sketch Session', 'description': 'Grab a pen and sketch anything for 10 minutes. Doodles, shapes, a portrait, a cartoon. Creative output feeds the ADHD brain.', 'conditionType': 'adhd', 'category': 'dopamineBoost', 'durationMinutes': 10, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_puzzle_quick_10m', 'title': 'Quick Puzzle', 'description': 'Do a quick puzzle — a word game, logic puzzle, or brain teaser. The challenge-reward loop gives your brain what it craves.', 'conditionType': 'adhd', 'category': 'dopamineBoost', 'durationMinutes': 10, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_sing_5m', 'title': 'Sing Your Favorite Song', 'description': 'Belt out your favorite song with full energy. Singing activates multiple brain areas and releases feel-good chemicals.', 'conditionType': 'adhd', 'category': 'dopamineBoost', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_organize_fun_10m', 'title': 'Satisfying Organizing', 'description': 'Organize something visually satisfying — color-sort books, arrange a drawer, line up items neatly. Feed the dopamine.', 'conditionType': 'adhd', 'category': 'dopamineBoost', 'durationMinutes': 10, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_drum_3m', 'title': 'Desk Drumming', 'description': 'Drum on your desk, knees, or any surface to a beat for 3 minutes. Rhythmic movement stimulates and regulates the ADHD brain.', 'conditionType': 'adhd', 'category': 'dopamineBoost', 'durationMinutes': 3, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_joke_5m', 'title': 'Joke Break', 'description': 'Read or watch jokes for 5 minutes. Laughter is a legit dopamine booster and can reset your focus for the next task.', 'conditionType': 'adhd', 'category': 'dopamineBoost', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_high_five_1m', 'title': 'Self High Five', 'description': 'Look in a mirror and give yourself a high five. Sounds silly, but it triggers a positive self-recognition response.', 'conditionType': 'adhd', 'category': 'dopamineBoost', 'durationMinutes': 1, 'timeOfDay': 'morning', 'difficulty': 'easy'},
  {'id': 'adhd_stretch_fun_5m', 'title': 'Fun Stretch Break', 'description': 'Do exaggerated, silly stretches — reach for the sky, twist like a pretzel, shake out your limbs. Movement + fun = dopamine.', 'conditionType': 'adhd', 'category': 'dopamineBoost', 'durationMinutes': 5, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_fidget_craft_10m', 'title': 'Fidget Craft', 'description': 'Make a simple fidget toy or work on a small craft. Keeping your hands busy helps your brain focus better.', 'conditionType': 'adhd', 'category': 'dopamineBoost', 'durationMinutes': 10, 'timeOfDay': 'anytime', 'difficulty': 'easy'},
  {'id': 'adhd_beat_box_3m', 'title': 'Beat Boxing', 'description': 'Try beat boxing for 3 minutes. Making rhythmic sounds engages your brain in a fun, stimulating way.', 'conditionType': 'adhd', 'category': 'dopamineBoost', 'durationMinutes': 3, 'timeOfDay': 'anytime', 'difficulty': 'easy'},

  // ═══════════════════════════════════════════════════════════════════════════
  // ADHD — Time Awareness
  // ═══════════════════════════════════════════════════════════════════════════
  {'id': 'adhd_time_check_3m', 'title': 'Time Estimation Practice', 'description': 'Before starting a task, guess how long it will take. Then time yourself. Compare. This trains time awareness.', 'conditionType': 'adhd', 'category': 'cognitiveTask', 'durationMinutes': 3, 'timeOfDay': 'morning', 'difficulty': 'easy'},
  {'id': 'adhd_timer_set_5m', 'title': 'Set Timers for Tasks', 'description': 'Break your next 2 hours into timed blocks. Set a timer for each task. When it rings, switch tasks. Build time structure.', 'conditionType': 'adhd', 'category': 'organizationalTask', 'durationMinutes': 5, 'timeOfDay': 'morning', 'difficulty': 'easy'},
